    kept = list(filter_records(RECORDS, min_level="warning"))
    assert [r.level for r in kept] == ["WARNING", "ERROR"]


def test_components():
    kept = list(filter_records(RECORDS, components=["db"]))
    assert {r.component for r in kept} == {"db"}
    assert len(kept) == 2


